package main

import (
	"bytes"
	"embed"
	"encoding/json"
	"flag"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"
	"time"
)

//go:embed index.html
var staticFS embed.FS

// --- Data types matching the CLI's checkpoint metadata ---

type TokenUsage struct {
	InputTokens         int         `json:"input_tokens"`
	CacheCreationTokens int         `json:"cache_creation_tokens"`
	CacheReadTokens     int         `json:"cache_read_tokens"`
	OutputTokens        int         `json:"output_tokens"`
	APICallCount        int         `json:"api_call_count"`
	SubagentTokens      *TokenUsage `json:"subagent_tokens,omitempty"`
}

type InitialAttribution struct {
	CalculatedAt    time.Time `json:"calculated_at"`
	AgentLines      int       `json:"agent_lines"`
	HumanAdded      int       `json:"human_added"`
	HumanModified   int       `json:"human_modified"`
	HumanRemoved    int       `json:"human_removed"`
	TotalCommitted  int       `json:"total_committed"`
	AgentPercentage float64   `json:"agent_percentage"`
}

type Summary struct {
	Intent    string   `json:"intent"`
	Outcome   string   `json:"outcome"`
	Friction  []string `json:"friction,omitempty"`
	OpenItems []string `json:"open_items,omitempty"`
}

// CommittedMetadata mirrors the per-session metadata.json on entire/checkpoints/v1.
type CommittedMetadata struct {
	CheckpointID       string              `json:"checkpoint_id"`
	SessionID          string              `json:"session_id"`
	Strategy           string              `json:"strategy"`
	CreatedAt          string              `json:"created_at"`
	Agent              string              `json:"agent,omitempty"`
	CheckpointsCount   int                 `json:"checkpoints_count"`
	FilesTouched       []string            `json:"files_touched"`
	TokenUsage         *TokenUsage         `json:"token_usage,omitempty"`
	Summary            *Summary            `json:"summary,omitempty"`
	InitialAttribution *InitialAttribution `json:"initial_attribution,omitempty"`
}

// CheckpointSummary mirrors the root metadata.json on entire/checkpoints/v1.
type CheckpointSummary struct {
	CheckpointID     string      `json:"checkpoint_id"`
	Strategy         string      `json:"strategy"`
	CheckpointsCount int         `json:"checkpoints_count"`
	FilesTouched     []string    `json:"files_touched"`
	TokenUsage       *TokenUsage `json:"token_usage,omitempty"`
}

// --- API response types ---

type CheckpointResponse struct {
	Hash         string             `json:"hash"`
	ShortHash    string             `json:"short_hash"`
	Subject      string             `json:"subject"`
	Date         string             `json:"date"`
	CheckpointID string             `json:"checkpoint_id"`
	Metadata     *CommittedMetadata `json:"metadata,omitempty"`
	RootMeta     *CheckpointSummary `json:"root_metadata,omitempty"`
}

type SessionResponse struct {
	SessionID    string   `json:"session_id"`
	Phase        string   `json:"phase"`
	AgentType    string   `json:"agent_type"`
	StartedAt    string   `json:"started_at"`
	FirstPrompt  string   `json:"first_prompt"`
	StepCount    int      `json:"step_count"`
	BaseCommit   string   `json:"base_commit"`
	FilesTouched []string `json:"files_touched"`
}

// --- Cached git common dir ---

var (
	gitCommonDirOnce sync.Once
	gitCommonDirVal  string
)

func gitCommonDir() string {
	gitCommonDirOnce.Do(func() {
		out, err := exec.Command("git", "rev-parse", "--git-common-dir").Output()
		if err != nil {
			log.Printf("warning: git rev-parse --git-common-dir failed: %v", err)
			gitCommonDirVal = ".git"
			return
		}
		gitCommonDirVal = strings.TrimSpace(string(out))
	})
	return gitCommonDirVal
}

func currentBranch() string {
	out, err := exec.Command("git", "rev-parse", "--abbrev-ref", "HEAD").Output()
	if err != nil {
		return "unknown"
	}
	return strings.TrimSpace(string(out))
}

// gitLog returns recent commits with checkpoint trailers.
func gitLog(limit int) []CheckpointResponse {
	// Format: hash\0subject\0date\0trailer_value
	format := "%H%x00%s%x00%aI%x00%(trailers:key=Entire-Checkpoint,valueonly)"
	out, err := exec.Command("git", "log", fmt.Sprintf("--format=%s", format), fmt.Sprintf("-%d", limit)).Output()
	if err != nil {
		log.Printf("git log failed: %v", err)
		return nil
	}

	var results []CheckpointResponse
	for _, line := range strings.Split(strings.TrimSpace(string(out)), "\n") {
		if line == "" {
			continue
		}
		parts := strings.SplitN(line, "\x00", 4)
		if len(parts) < 4 {
			continue
		}
		cpID := strings.TrimSpace(parts[3])
		if cpID == "" {
			continue
		}
		hash := parts[0]
		short := hash
		if len(short) > 7 {
			short = short[:7]
		}
		results = append(results, CheckpointResponse{
			Hash:         hash,
			ShortHash:    short,
			Subject:      parts[1],
			Date:         parts[2],
			CheckpointID: cpID,
		})
	}
	return results
}

// readCheckpointMeta reads the per-session metadata for a checkpoint from entire/checkpoints/v1.
func readCheckpointMeta(cpID string) (*CommittedMetadata, error) {
	if len(cpID) < 3 {
		return nil, fmt.Errorf("checkpoint ID too short: %s", cpID)
	}
	shard := cpID[:2]
	rest := cpID[2:]
	// Try session 0 metadata first (per-session metadata with full details)
	path := fmt.Sprintf("entire/checkpoints/v1:%s/%s/0/metadata.json", shard, rest)
	out, err := exec.Command("git", "show", path).Output()
	if err != nil {
		return nil, fmt.Errorf("git show %s: %w", path, err)
	}
	var meta CommittedMetadata
	if err := json.Unmarshal(out, &meta); err != nil {
		return nil, fmt.Errorf("unmarshal metadata: %w", err)
	}
	return &meta, nil
}

// readCheckpointSummary reads the root metadata.json for a checkpoint.
func readCheckpointSummary(cpID string) (*CheckpointSummary, error) {
	if len(cpID) < 3 {
		return nil, fmt.Errorf("checkpoint ID too short: %s", cpID)
	}
	shard := cpID[:2]
	rest := cpID[2:]
	path := fmt.Sprintf("entire/checkpoints/v1:%s/%s/metadata.json", shard, rest)
	out, err := exec.Command("git", "show", path).Output()
	if err != nil {
		return nil, fmt.Errorf("git show %s: %w", path, err)
	}
	var summary CheckpointSummary
	if err := json.Unmarshal(out, &summary); err != nil {
		return nil, fmt.Errorf("unmarshal summary: %w", err)
	}
	return &summary, nil
}

// readSessions reads active session files from .git/entire-sessions/.
func readSessions() []SessionResponse {
	dir := filepath.Join(gitCommonDir(), "entire-sessions")
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil
	}

	var sessions []SessionResponse
	for _, entry := range entries {
		if !strings.HasSuffix(entry.Name(), ".json") {
			continue
		}
		data, err := os.ReadFile(filepath.Join(dir, entry.Name()))
		if err != nil {
			continue
		}
		// Parse into a generic map first since we only need a subset of fields
		var raw map[string]json.RawMessage
		if err := json.Unmarshal(data, &raw); err != nil {
			continue
		}

		s := SessionResponse{}
		readString(raw, "session_id", &s.SessionID)
		readString(raw, "phase", &s.Phase)
		readString(raw, "agent_type", &s.AgentType)
		readString(raw, "started_at", &s.StartedAt)
		readString(raw, "first_prompt", &s.FirstPrompt)
		readString(raw, "base_commit", &s.BaseCommit)
		readInt(raw, "checkpoint_count", &s.StepCount)
		readStringSlice(raw, "files_touched", &s.FilesTouched)

		if s.SessionID != "" {
			sessions = append(sessions, s)
		}
	}
	return sessions
}

func readString(m map[string]json.RawMessage, key string, dst *string) {
	if v, ok := m[key]; ok {
		json.Unmarshal(v, dst)
	}
}

func readInt(m map[string]json.RawMessage, key string, dst *int) {
	if v, ok := m[key]; ok {
		json.Unmarshal(v, dst)
	}
}

func readStringSlice(m map[string]json.RawMessage, key string, dst *[]string) {
	if v, ok := m[key]; ok {
		json.Unmarshal(v, dst)
	}
}

func handleCheckpoints(w http.ResponseWriter, _ *http.Request) {
	checkpoints := gitLog(50)
	if checkpoints == nil {
		checkpoints = []CheckpointResponse{}
	}

	// Enrich with metadata (in parallel for speed)
	var wg sync.WaitGroup
	for i := range checkpoints {
		wg.Add(1)
		go func(idx int) {
			defer wg.Done()
			cp := &checkpoints[idx]
			meta, err := readCheckpointMeta(cp.CheckpointID)
			if err != nil {
				log.Printf("metadata for %s: %v", cp.CheckpointID, err)
				return
			}
			cp.Metadata = meta

			summary, err := readCheckpointSummary(cp.CheckpointID)
			if err != nil {
				log.Printf("summary for %s: %v", cp.CheckpointID, err)
				return
			}
			cp.RootMeta = summary
		}(i)
	}
	wg.Wait()

	writeJSON(w, checkpoints)
}

func handleSessions(w http.ResponseWriter, _ *http.Request) {
	sessions := readSessions()
	if sessions == nil {
		sessions = []SessionResponse{}
	}
	writeJSON(w, sessions)
}

func handleBranch(w http.ResponseWriter, _ *http.Request) {
	writeJSON(w, map[string]string{"branch": currentBranch()})
}

func writeJSON(w http.ResponseWriter, data any) {
	w.Header().Set("Content-Type", "application/json")
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetIndent("", "  ")
	if err := enc.Encode(data); err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	w.Write(buf.Bytes())
}

func main() {
	port := flag.Int("port", 8080, "HTTP server port")
	flag.Parse()

	// Verify we're in a git repo
	if err := exec.Command("git", "rev-parse", "--git-dir").Run(); err != nil {
		fmt.Fprintln(os.Stderr, "error: not a git repository. Run from within a git repo.")
		os.Exit(1)
	}

	http.HandleFunc("/api/checkpoints", handleCheckpoints)
	http.HandleFunc("/api/sessions", handleSessions)
	http.HandleFunc("/api/branch", handleBranch)

	// Serve embedded index.html
	http.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/" {
			http.NotFound(w, r)
			return
		}
		data, err := staticFS.ReadFile("index.html")
		if err != nil {
			http.Error(w, "internal error", http.StatusInternalServerError)
			return
		}
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		w.Write(data)
	})

	addr := fmt.Sprintf(":%d", *port)
	fmt.Fprintf(os.Stderr, "Checkpoint Viewer listening on http://localhost%s\n", addr)
	log.Fatal(http.ListenAndServe(addr, nil))
}

