// readAllCheckpointSessions reads all per-session metadata for a checkpoint from entire/checkpoints/v1.
// Sessions are stored in 0/, 1/, 2/... subdirectories. We probe sequentially until one fails.
func readAllCheckpointSessions(cpID string) []CommittedMetadata {
	if len(cpID) < 3 {
		return nil
	}
	shard := cpID[:2]
	rest := cpID[2:]

	var sessions []CommittedMetadata
	for i := 0; i < 20; i++ { // cap at 20 sessions per checkpoint
		path := fmt.Sprintf("entire/checkpoints/v1:%s/%s/%d/metadata.json", shard, rest, i)
		out, err := exec.Command("git", "show", path).Output()
		if err != nil {
			break
		}
		var meta CommittedMetadata
		if err := json.Unmarshal(out, &meta); err != nil {
			break
		}
		sessions = append(sessions, meta)
	}
	return sessions
}

